const tryInsertRunSlot = `-- name: TryInsertRunSlot :execrows
INSERT INTO run_slots (holder_id, kind, connection_id)
SELECT $1, $2, $3
WHERE (SELECT count(*) FROM run_slots) < $4::bigint
  AND (SELECT count(*) FROM run_slots WHERE connection_id = $3)
      < COALESCE((SELECT c.max_concurrent_runs::bigint FROM connections c WHERE c.id = $3),
                 $5::bigint)
ON CONFLICT (holder_id) DO NOTHING
`

type TryInsertRunSlotParams struct {
	HolderID         uuid.UUID `json:"holderId"`
	Kind             string    `json:"kind"`
	ConnectionID     uuid.UUID `json:"connectionId"`
	MaxGlobal        int64     `json:"maxGlobal"`
	MaxPerConnection int64     `json:"maxPerConnection"`
}

// TryInsertRunSlot takes a slot when both the global and the per-connection
// limit leave room (run under LockRunSlots). The per-connection limit is the
// connection's max_concurrent_runs (task 3.13, D-156) or, when NULL,
// @max_per_connection (workers.max_runs_per_connection).
func (q *Queries) TryInsertRunSlot(ctx context.Context, arg TryInsertRunSlotParams) (int64, error) {
	result, err := q.db.Exec(ctx, tryInsertRunSlot,
		arg.HolderID,
		arg.Kind,
		arg.ConnectionID,
		arg.MaxGlobal,
		arg.MaxPerConnection,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
